<div class="section-head"><div><p class="eyebrow">ADMINISTRATION</p><h1>Settings</h1></div></div>
<?php if($settingsUser['role']==='superadmin'):?><section class="panel settings-section"><h2>Brand icon</h2><form method="post" action="/admin/settings/icon" enctype="multipart/form-data" class="stack"><?=csrf()?><?php if($brandIcon):?><div class="brand-preview"><img src="/uploads/<?=e($brandIcon)?>" alt="Current brand icon"><span>Current icon</span></div><?php endif?><label>Upload an icon <small>JPEG, PNG, WebP, or GIF. A square image works best.</small><input type="file" name="brand_icon" accept="image/jpeg,image/png,image/webp,image/gif" <?=$brandIcon?'':'required'?>></label><div class="inline"><button>Save icon</button><?php if($brandIcon):?><button class="secondary" name="remove" value="1" formnovalidate>Use default pie</button><?php endif?></div></form></section><section class="panel settings-section"><h2>Sessions</h2><form method="post" action="/admin/settings" class="stack"><?=csrf()?><label>Session inactivity timeout <small>Minutes before inactive users must sign in again. Enter 0 for no inactivity timeout.</small><input type="number" name="session_timeout_minutes" value="<?=e($sessionMinutes)?>" min="0" max="5256000" required inputmode="numeric"></label><button>Save session settings</button></form><p class="muted">Changes apply globally. Existing sessions use the new timeout on their next request.</p></section><?php endif?>
